"use client";
import {useState} from 'react';import{createClient}from '@/lib/supabase/client';
export default function ResetPasswordPage(){const[p,setP]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);const{error}=await createClient().auth.updateUser({password:p});setMsg(error?error.message:'Password updated.');setBusy(false);}return <main className="auth-page"><div className="auth-card"><div className="eyebrow">Account recovery</div><h1>Choose a new password.</h1><p className="muted">Use at least 12 characters.</p><form onSubmit={submit} className="auth-form"><label htmlFor="password">New password</label><input id="password" type="password" minLength={12} required value={p} onChange={e=>setP(e.target.value)}/><button className="primary-button" disabled={busy}>{busy?'Updating…':'Set new password'}</button></form>{msg&&<p className="auth-message" role="status">{msg}</p>}</div></main>}
